// @vitest-environment node
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import sharp from 'sharp';
import { manifest } from './manifest.js';

/**
 * [P31] The installed app had no recognisable icon: every manifest icon was a flat blue square (a July
 * placeholder), and no page declared a favicon or an apple-touch-icon. The icon is now the brand mark — the
 * wordmark's terracotta Fraunces "T" on the paper background — generated by apps/web/scripts/gen-icons.mjs.
 */
const pub = (p: string) => resolve(process.cwd(), 'apps/web/public', p.replace(/^\//, ''));
const PAPER = { r: 0xf4, g: 0xf1, b: 0xea };
const TERRACOTTA = { r: 0xd1, g: 0x48, b: 0x21 };
const near = (a: { r: number; g: number; b: number }, b: { r: number; g: number; b: number }) =>
  Math.abs(a.r - b.r) + Math.abs(a.g - b.g) + Math.abs(a.b - b.b) < 24;

async function look(file: string) {
  const img = sharp(readFileSync(pub(file)));
  const meta = await img.metadata();
  const { data, info } = await img.removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const px = (x: number, y: number) => { const i = (y * info.width + x) * 3; return { r: data[i]!, g: data[i + 1]!, b: data[i + 2]! }; };
  let terracotta = 0;
  for (let i = 0; i < data.length; i += 3) if (near({ r: data[i]!, g: data[i + 1]!, b: data[i + 2]! }, TERRACOTTA)) terracotta += 1;
  return { meta, corner: px(1, 1), centre: px(Math.floor(info.width / 2), Math.floor(info.height / 2)), terracottaShare: terracotta / (info.width * info.height) };
}

describe('[P31] app icons are the brand mark, not placeholders', () => {
  const files = [
    ...manifest.icons.map((i) => ({ src: i.src, size: Number(i.sizes.split('x')[0]) })),
    { src: '/apple-touch-icon.png', size: 180 },
    { src: '/favicon-32.png', size: 32 },
  ];
  for (const f of files) {
    it(`${f.src} is a ${f.size}px PNG: paper background with the terracotta T in the middle`, async () => {
      const { meta, corner, centre, terracottaShare } = await look(f.src);
      expect(meta.format).toBe('png');
      expect([meta.width, meta.height]).toEqual([f.size, f.size]);
      expect(near(corner, PAPER)).toBe(true);            // paper, not the old blue
      expect(near(centre, TERRACOTTA)).toBe(true);       // the T's stem runs through the centre
      expect(terracottaShare).toBeGreaterThan(0.04);     // a real mark, not a dot
      expect(terracottaShare).toBeLessThan(0.5);         // and not a flat fill
    });
  }

  it('the maskable icon keeps the T inside the safe zone (central 80% circle)', async () => {
    const img = sharp(readFileSync(pub('/icons/icon-maskable-512.png')));
    const { data, info } = await img.removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const r = info.width * 0.4; const c = info.width / 2;
    let outside = 0;
    for (let y = 0; y < info.height; y++) for (let x = 0; x < info.width; x++) {
      const i = (y * info.width + x) * 3;
      if (near({ r: data[i]!, g: data[i + 1]!, b: data[i + 2]! }, TERRACOTTA) && Math.hypot(x - c, y - c) > r) outside += 1;
    }
    expect(outside).toBe(0);
  });

  it('every page declares the favicon and the apple-touch-icon (iOS ignores manifest icons)', () => {
    for (const page of ['apps/web/index.html', 'apps/web/app.html', 'apps/web/privacy/index.html', 'apps/web/terms/index.html']) {
      const html = readFileSync(resolve(process.cwd(), page), 'utf8');
      expect(html, page).toMatch(/<link rel="icon" type="image\/png" sizes="32x32" href="\/favicon-32\.png" \/>/);
      expect(html, page).toMatch(/<link rel="apple-touch-icon" href="\/apple-touch-icon\.png" \/>/);
    }
  });
});
